        script: 'There are various influences on the way we choose to dress everyday. Weather is one of them. Like, on rainy days, you\'d want to choose clothes that are comfortable, not bright-colored, and light, while on sunnier, hotter days, flowy and breathable pieces will be much more preferable. Another factor is the event that you\'re dressing for. For example, you need to wear something dark and modest for funerals, while weddings allow the attendees to wear something more out-of-the-box and fun. Last but not least, I think that age also has something to do with clothing. As for older people, they may choose stable pieces, but younger ones won\'t be afraid to wear something more experimental.',
