        instruction: 'Nghe câu gốc, rồi nói lại bằng cách diễn đạt trong khung bên dưới.',
        prompt: 'What effects can watching television have on children?\nAspects:\n+ health: glued to the screen for a long time >> lead a sedentary lifestyle >> more likely to develop obesity and eyesight issues\n+ social: sit in front of TV all day >> distract children from outdoor activities >> reduced ability to communicate/socialise with other people >> even higher risk of autism',
        script: 'Watching television can cause lots of problems for children. From a health perspective, spending a long time glued to the screen can lead to a sedentary lifestyle, which in turn increases the risk of obesity and eye problems. Children who watch a lot of TV may not get enough physical activity, which is essential for their overall health and well-being. From a social perspective, spending all day in front of the TV can also distract children from outdoor activities and limit their ability to interact and communicate with others. This lack of socialization can even increase the risk of autism in some children. Children need to be active and engage in social interactions to develop healthy relationships and strong communication skills.',
