        script: 'There are various reasons why people choose to write online reviews, depending on what aspects we\'re looking at. Firstly, one of the key motivators is financial incentives. Some companies offer discounts or rewards for customers who leave a review on their products. This incentivizes people to write a review in order to save money on their next purchase. On the other hand, people may also write reviews to express their emotions and opinions about the products they have purchased. They might want to share their experience and give their thoughts on the product\'s quality, design, and overall performance. For example, if they were unhappy with a low-quality product, they may write a negative review in order to vent their frustration and to warn other customers about the product\'s poor performance.',
