        prompt: 'Has travel become safer in recent years than that was in the past?\nAspects:\n+ health hazard: have clear procedures to separate ill customers from healthy ones + regular cleaning of vehicles >> less likely to spread diseases\n+ weather hazard: systems to predict weather patterns + AI to autopilot >> reduce the risk of accidents in extreme weather cases',
        script: 'In my opinion, travel has definitely become safer in recent years. There are a few aspects to consider when evaluating travel safety. Firstly, there are health hazards that are addressed more effectively now compared to the past. For instance, there are clear procedures in place to separate ill customers from healthy ones, and there are regular cleaning processes in place for vehicles to reduce the risk of spreading diseases. Secondly, there are weather hazards that are better managed now. With the help of technology such as systems to predict weather patterns and AI that can assist with autopiloting, we can reduce the risk of accidents in extreme weather cases. These advancements have made travel much safer than it was in the past.',
