        script: 'Definitely not, since there are many problems that can take place. As for their mental health, the internet can have adverse effects on children\'s well-being. They may be exposed to inappropriate content or be bullied and harassed online, which can lead to serious mental issues. It\'s essential for parents to supervise their children\'s internet usage and monitor the content they are accessing. When it comes to social issues, the internet can also be dangerous in terms of social security. Children may meet strangers online who can scam them or put them in dangerous situations. Hence, it is vital to educate children on the dangers of the internet and the importance of being cautious when interacting with people online.',
