        instruction: 'Nghe câu gốc, rồi nói lại bằng cách diễn đạt trong khung bên dưới.',
        prompt: 'How important is it for companies to take all customer complaints seriously?\nAspects:\n+ reputation: unsatisfied customers share negative reviews >> affect brand reputation >> lose prospective customers\n+ quality: complaints are a source of feedback >> can’t improve quality without taking complaints into consideration',
        script: 'Absolutely, taking customer complaints seriously is crucial for companies in many ways. Firstly, a company\'s reputation can be severely impacted if they do not address customer complaints properly. An unsatisfied customer may spread negative reviews and comments about their experiences, which could discourage other prospective customers from using their products or services. This can have a significant impact on the company\'s brand image and business growth. Also, customer complaints are a valuable source of feedback for companies. By ignoring customer complaints, a company may miss out on the opportunity to identify areas where they need to improve. For example, if a customer is complaining about the quality of a product, it means that the company should work on improving that aspect. Without taking customer complaints seriously, companies cannot guarantee they will maintain high-quality standards and continue to meet customer expectations.',
