        type: 'repeat',
        id: '-VtZaf-ruyPuw7PJIQTj6',
        instruction: 'Nghe câu gốc, rồi nói lại bằng cách diễn đạt trong khung bên dưới.',
        prompt: 'How has the internet changed the way we live?',
        script: 'The internet has brought about many significant changes in the way we live, particularly for workers and students. In terms of workers, the internet has expanded the pool of job opportunities, making it easier for them to find work and connect with potential employers. It has also empowered workers by providing more information about job markets and salaries, giving them more negotiation power. With the internet, workers are no longer at the mercy of their employers, as they can easily find alternative job options and compare offers. For students, the internet has revolutionized the way they access and acquire knowledge. With online resources and educational platforms, students now have access to up-to-date information and a wealth of learning materials. The internet has also bridged the gap between students from developed and developing countries, providing greater equality in access to education. With the internet, students can now connect with peers and teachers from all over the world, further expanding their knowledge and perspectives.',
