        prompt: 'Do you think an area can benefit from having an interesting historic place?\nPerspective:\n+ Short-term: attract more tourists >> develop tourism >> generate more income for the economy\n+ long-term: maintain historical values >> next generations learn about the values and sacrifices of their ancestors >> feel appreciative',
        script: 'Yes, I believe an area can benefit greatly from having an interesting historic place. From a short-term perspective, having a historic place can attract more tourists, which can help develop tourism and generate more income for the local economy. From a long-term perspective, having a historic place can help maintain the historical values of the area, as future generations can learn about the values and sacrifices of their ancestors, which can make them feel appreciative and more connected to their heritage.',
